                return AVERROR(EIO);

            }

            mms->asf_header_size = len;

            if (!mms->header_parsed) {

                res = ff_mms_asf_header_parser(mms);

                mms->header_parsed = 1;

                return res;

            }

        } else if (chunk_type == CHUNK_TYPE_DATA) {

            // read data packet and do padding

            return read_data_packet(mmsh, len);

        } else {

            if (len) {

                if (len > sizeof(mms->in_buffer)) {

